/* Learn English — reading passages ("unseen"): four levels for every topic
   (level 1 easiest, level 4 hardest) and a general reading library.
   Loaded after english-data.js; adds each topic's passages to its exercises
   (type "reading") and adds the library as its own topic.

   Unit: { level, title, text: [paragraphs], glossary?: [{ en, he }], mark?, questions }
   - text: a word in [brackets] (or [two words]) is one the student has to
     find and click in the marking stage. Every occurrence of the topic's
     words must be bracketed — an unbracketed one would count as a wrong click.
   - mark: what to find, { text, textEn, hint } — merged over the topic's
     MARK entry. Library passages have no marking stage.
   - questions, in the order of the text:
       { type: "mc", q, he, options: [...], optionsHe: [...], answer }   answer is one of the options
       { type: "tf", q, he, answer: true | false }
       { type: "open", q, lang: "he" | "en", answer, keywords, qEn?, answerEn?, he? }
     `he` (and `optionsHe`, in the order of `options`) is what the runner's
     "Hebrew questions" switch shows. Levels 1–2: open questions are asked and
     answered in Hebrew (`qEn` / `answerEn` and English keywords serve the
     English UI). Levels 3–4: open questions carry `he` but are still
     answered in English.
   - Words in the passage get their meaning for "Translate words" from
     english-dict.js; a passage may add its own as `words: { word: meaning }`.
     keywords: groups of words; an answer is right when it contains a word
     from every group. English keywords match the start of a word ("play"
     matches "played"), Hebrew ones anywhere in the answer. An empty list
     accepts any answer (opinion questions). */

